/*
 * OpenJDK 25 HotSpot jfr/periodic/jfrPeriodic.hpp port
 *
 * JfrPeriodic — base class for periodic events. Periodic events are
 * generated by the JfrPeriodicEventSet on a timer/interval.
 */

use crate::share::jfr::utilities::jfr_types::JfrEventId;

// Request types matching the C++ enum.
pub const REQUEST_RUNNING: u32 = 0;
pub const REQUEST_SCHEDULED: u32 = 1;
pub const REQUEST_PERIODIC: u32 = 2;
pub const REQUEST_ONE_SHOT: u32 = 4;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct JfrPeriodicRequest {
    pub event_id: JfrEventId,
    pub interval_ms: u64,
    pub request_type: u32,
}

pub trait JfrPeriodicEvent: Send + Sync {
    fn event_id(&self) -> JfrEventId;
    fn request(&self) -> JfrPeriodicRequest;
    fn on_rotation(&self) {}
    fn on_stop(&self) {}
}
